// Solo genera contexto para los pendientes que llegan ya filtrados
const inItems = $input.all();
const out = [];

for (let i = 0; i < inItems.length; i++) {
  const { json } = inItems[i];

  const d = String(json.DIA_DEL_EVENTO || '').split('/');
  const year = d[2] || String(new Date().getFullYear());

  const promoter = String(json.ORGANIZADOR || '').trim() || 'SIN IDENTIFICAR';
  const base = String(json.CODIGO_INTERNO || 'SIN-CODIGO').trim();

  const fileBase = (json.CODIGO_TCOM && String(json.CODIGO_TCOM).trim())
    ? `${String(json.CODIGO_TCOM).trim()}-${base}`
    : base;

  out.push({
    json: {
      CODIGO_INTERNO: base,
      folder: `/${year}/${promoter}`,
      fileBase,
      pdfName: `${fileBase}.jpg`,
      htmlName: `${fileBase}.html`,
      urlEvento: String(json.URL_EVENTO).trim()
    },
    pairedItem: { item: i }
  });
}

return out;

// ==== Helpers ====
function firstNonEmpty(...v){ for (const x of v) if (x && String(x).trim()) return String(x).trim(); return ""; }
function isAbs(u){ return /^https?:\/\//i.test(u || ""); }
function quitarAcentos(t){ if(!t) return ""; return t.normalize("NFD").replace(/(?!ñ)[\u0300-\u036f]/g,"").replace(/[\u201C\u201D]/g,'"').replace(/[\u2018\u2019]/g,"'").trim(); }
function originFrom(u){ try { return new URL(u).origin; } catch { return ""; } }
function originLoose(u){ if(!u) return ""; const m=String(u).match(/^(https?:\/\/[^/]+)/i); return m?m[1]:""; }
function toAbs(u, origin, pageUrl){
  if (!u) return "";
  u = String(u).trim();
  if (!u) return "";
  if (isAbs(u)) return u;
  if (u.startsWith("//")) return "https:" + u;
  if (u.startsWith("/") && origin) return origin + u;
  try { return new URL(u, pageUrl || origin || undefined).toString(); } catch { return u; }
}

// ==== Contexto ====
const pageUrl = $node["SET - CTX"]?.json?.CTX?.urlEvento || $json?.CTX?.urlEvento || "";

// Calcula un origin robusto: primero desde pageUrl, si no, desde cualquier URL absoluta visible
let baseOrigin = originFrom(pageUrl);
if (!baseOrigin) {
  const anyAbs = firstNonEmpty(
    $json.URL_CARTEL_DETALLE,
    $json.URL_TICKETS_BTN,
    $json.URL_TICKETS,
    $json.URL_TICKETS_IFRAME,
    pageUrl
  );
  baseOrigin = originFrom(anyAbs) || originLoose(anyAbs) || originLoose(pageUrl) || "";
}

// ==== Transformación item a item ====
return items.map(it => {
  const j = it.json || {};

  // Hora -> HH:MM (primera que aparezca)
  const hMatch = String(j.HORA || "").match(/\d{1,2}:\d{2}/);
  const HORA_EVENTO = hMatch ? hMatch[0] : "";

  // Cartel: meta > twitter/meta-secure > link > detalle
  const rawCartel = firstNonEmpty(j.URL_CARTEL_META, j.URL_CARTEL_META_TW, j.URL_CARTEL_LINK, j.URL_CARTEL_DETALLE);
  const URL_CARTEL_EVENTO = toAbs(rawCartel, baseOrigin, pageUrl);

  // Ticket: botón > genérico > iframe
  const rawTicket = firstNonEmpty(j.URL_TICKETS_BTN, j.URL_TICKETS, j.URL_TICKETS_IFRAME);
  const URL_TICKET = toAbs(rawTicket, baseOrigin, pageUrl);

  // Observaciones
  let obs = j.OBSERVACIONES_GENERALES || "";
  if (Array.isArray(obs)) obs = obs.join(" ").replace(/\s+/g, " ");
  obs = quitarAcentos(obs);

  return {
    json: {
      ...j,
      HORA_EVENTO,
      URL_CARTEL_EVENTO,
      URL_TICKET,
      OBSERVACIONES_GENERALES: obs,
      VALID_CARTEL: isAbs(URL_CARTEL_EVENTO),
      _DEBUG_PAGE_URL: pageUrl,
      _DEBUG_BASE_ORIGIN: baseOrigin,
      _DEBUG_RAW_CARTEL: rawCartel,
      _DEBUG_RAW_TICKET: rawTicket
    }
  };
});

// Deja 1 por CODIGO_INTERNO y solo los que necesitan captura
const items = $input.all();
const seen = new Set();
const out = [];

for (const it of items) {
  const j = it.json || {};
  const id = String(j.CODIGO_INTERNO || '').trim();
  if (!id) continue;                          // sin ID, descarta
  if (seen.has(id)) continue;                 // duplicado
  seen.add(id);

  if (j["ARCHIVO_CAPTURA_(DRIVE)"]) continue; // ya capturado
  if (!j.URL_EVENTO || !/^https?:\/\//i.test(j.URL_EVENTO)) continue; // sin URL válida

  out.push(it);                               // pasa adelante
}
return out;

function firstNonEmpty(...vals){
  for (const v of vals){
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return undefined; // ← Cambio clave: retornar undefined en vez de ''
}

function safeNodeJson(name, idx){
  try{
    const it = $items(name, 0, idx);
    return (it && it[0] && it[0].json) || {};
  }catch(e){
    return {};
  }
}

const srcIndex =
  ($input.item && $input.item.pairedItem && typeof $input.item.pairedItem.item === 'number')
    ? $input.item.pairedItem.item
    : $itemIndex;

const ctx    = (safeNodeJson('SET - CTX', srcIndex).CTX) || {};
const upHtml = safeNodeJson('Upload a file', srcIndex);
const upShot = safeNodeJson('Upload Screenshot to Dropbox PNG', srcIndex);
const upCart = safeNodeJson('Upload a file1', srcIndex);
const norm   = safeNodeJson('Code Normalizador', srcIndex);
const cur    = $json || {};
const existing = safeNodeJson('Get row(s) in sheet', srcIndex);

// 🔥 Construcción del objeto solo con campos NO vacíos
const result = {
  CODIGO_INTERNO: firstNonEmpty(ctx.CODIGO_INTERNO, cur.CODIGO_INTERNO, norm.CODIGO_INTERNO, existing.CODIGO_INTERNO)
};

// Solo agregar campos si tienen valor
const capturaHtml = firstNonEmpty(upHtml.path_display, upHtml.path_lower, existing['ARCHIVO_CAPTURA_(DRIVE)']);
if (capturaHtml) result['ARCHIVO_CAPTURA_(DRIVE)'] = capturaHtml;

const fechaCaptura = firstNonEmpty(upHtml.client_modified, existing.FECHA_CAPTURA);
if (fechaCaptura) result.FECHA_CAPTURA = fechaCaptura;

const capturaPng = firstNonEmpty(upShot.path_lower, upShot.path_display, upShot.name, existing.ARCHIVO_CAPTURA_PNG);
if (capturaPng) result.ARCHIVO_CAPTURA_PNG = capturaPng;

const cartel = firstNonEmpty(upCart.path_lower, upCart.path_display, existing['ARCHIVO_CARTEL_(DRIVE)']);
if (cartel) result['ARCHIVO_CARTEL_(DRIVE)'] = cartel;

const hora = firstNonEmpty(cur.HORA_EVENTO, norm.HORA_EVENTO, existing.HORA_EVENTO);
if (hora) result.HORA_EVENTO = hora;

const ticket = firstNonEmpty(cur.URL_TICKET, norm.URL_TICKET, norm.URL_TICKETS, existing.URL_TICKET);
if (ticket) result.URL_TICKET = ticket;

const cartelEvento = firstNonEmpty(cur.URL_CARTEL_EVENTO, norm.URL_CARTEL_EVENTO, norm.URL_CARTEL_DETALLE, existing.URL_CARTEL_EVENTO);
if (cartelEvento) result.URL_CARTEL_EVENTO = cartelEvento;

const obs = firstNonEmpty(cur.OBSERVACIONES_GENERALES, norm.OBSERVACIONES_GENERALES, norm.OBS, existing.OBSERVACIONES_GENERALES);
if (obs) result.OBSERVACIONES_GENERALES = obs;

return [{ json: result }];
